package android.graphics;import java.awt.image.BufferedImage;public class Bitmap {public enum CompressFormat {PNG,JPEG}public boolean compress(CompressFormat format,int quality,java.io.OutputStream out){try{return javax.imageio.ImageIO.write(pixels,format==CompressFormat.PNG?"png":"jpg",out);}catch(java.io.IOException e){return false;}}public enum Config {ARGB_8888}public BufferedImage pixels;public Bitmap(BufferedImage b){pixels=b;}public int getWidth(){return pixels.getWidth();}public int getHeight(){return pixels.getHeight();}public boolean isRecycled(){return pixels==null;}public void recycle(){pixels=null;}public static Bitmap createBitmap(int w,int h,Config c){return new Bitmap(new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB));}public static Bitmap createBitmap(int[] p,int w,int h,Config c){BufferedImage b=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB);b.setRGB(0,0,w,h,p,0,w);return new Bitmap(b);}public static Bitmap createBitmap(Bitmap b,int x,int y,int w,int h){return new Bitmap(b.pixels.getSubimage(x,y,w,h));}public static Bitmap createScaledBitmap(Bitmap b,int w,int h,boolean filter){BufferedImage out=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB);java.awt.Graphics2D g=out.createGraphics();g.drawImage(b.pixels,0,0,w,h,null);g.dispose();return new Bitmap(out);}}